// Builds what the model will read, from the submission payload frozen at poll time.
// The contact is read only for what staff maintain (verified status, owner).
const start = $('Configuration').first().json;
const cfg = start.cfg, P = cfg.props;
const rec = $('Read contact').first().json;
const p = rec.properties || {};
const sub = start.payload || {};
const contact = {
  id: String(rec.id || start.contact_id),
  firstName: sub.firstName || '',
  lastName: sub.lastName || '',
  credentials: String(sub.credentials || '').trim(),
  message: String(sub.message || '').trim(),
  verifiedQmeStatus: p[P.verifiedQmeStatus] || null,
  ownerId: p.hubspot_owner_id || null,
};

// What this physician already wrote in earlier inquiries (validated readings, from the ledger).
const previously = {};
for (const it of $('Earlier readings').all()) {
  const r = it.json && it.json.model_result;
  if (!r) continue;
  if (!previously.specialty && r.specialty && r.specialty.value) previously.specialty = r.specialty.value;
  if (!previously.license_states && r.license_states && Array.isArray(r.license_states.value) && r.license_states.value.length) previously.license_states = r.license_states.value;
}

// Interpreted on an earlier attempt of THIS submission: reuse it (same frozen payload).
if (start.model_result) {
  return [{ json: { contact, previously, needsModel: false, reused: true, result: start.model_result } }];
}

// Too little text to interpret: plain code, no model call.
if (contact.message.replace(/\s+/g, ' ').length < 20) {
  const result = {
    specialty: { value: null, evidence: null },
    license_states: { value: null, evidence: null },
    states_not_licensed: { value: null, evidence: null },
    certification_statement: { value: 'not_stated', evidence: null },
    intent: { value: 'unclear', evidence: null },
    call_availability: { value: null, evidence: null },
    questions: [],
    ambiguities: ['The message is empty or too short to interpret.'],
    flags: ['no_model_call:message_too_short'],
    review_status: 'needs_information',
    proposed_reply: (contact.lastName ? 'Dear Dr. ' + contact.lastName : 'Hello') + ',\n\nThank you for reaching out about joining Expedient. To make our first conversation useful, could you tell us a little about your specialty, the states where you are licensed, and whether you are already a QME or exploring QME certification?\n\nBest regards,\n[Your name], Expedient recruiting',
    source: 'rules',
  };
  return [{ json: { contact, previously, needsModel: false, reused: false, result } }];
}

const input = {};
for (const f of cfg.modelFields) input[f] = contact[f];
input.known_to_team = !!contact.verifiedQmeStatus;   // staff have verified this physician's QME status
input.previously_stated = previously;
// One provider (OpenAI Chat Completions, pinned model snapshot), no fallback.
const modelRequest = {
  model: cfg.model,
  reasoning_effort: 'low',
  max_completion_tokens: 4000,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: "You read one message that a physician sent through the \"join us\" form of a California medical-legal evaluation company. The company works with Qualified Medical Evaluators (QMEs) and also helps physicians who are new to QME work. Your output helps a recruiting coordinator prepare a personal first conversation. A person reviews everything you produce; nothing is sent automatically.\n\nYou receive:\n- \"credentials\": the degree the physician picked in the form's select box (for example M.D. or D.O.);\n- \"message\": their free text;\n- \"known_to_team\": true when staff have already verified this physician's QME status (you never see that record);\n- \"previously_stated\": what this physician wrote in earlier inquiries, already checked (specialty, license states), or an empty object.\n\nReturn one JSON object and nothing else, with exactly these keys:\n{\n  \"specialty\":               {\"value\": string or null, \"evidence\": exact quote or null},\n  \"license_states\":          {\"value\": array of two-letter US state codes or null, \"evidence\": exact quote or null},\n  \"states_not_licensed\":     {\"value\": array of two-letter US state codes or null, \"evidence\": exact quote or null},\n  \"certification_statement\": {\"value\": \"says_certified_qme\" | \"says_lapsed\" | \"says_in_progress\" | \"says_not_certified\" | \"not_stated\", \"evidence\": exact quote or null},\n  \"intent\":                  {\"value\": \"explore_qme_certification\" | \"established_qme_joining\" | \"returning_qme\" | \"other\" | \"unclear\", \"evidence\": exact quote or null},\n  \"call_availability\":       {\"value\": string or null, \"evidence\": exact quote or null},\n  \"questions\":   [questions the physician asked, short],\n  \"ambiguities\": [only what a coordinator must clarify before a useful first conversation, short; empty if nothing],\n  \"proposed_reply\": string\n}\n\nRules:\n- Report only what the physician states in this message. If something is not stated, use null (or \"not_stated\" / \"unclear\"). A sparse message gives a sparse result; that is correct.\n- Every non-null value needs \"evidence\": a short quote copied word for word from the message. The quote is one continuous piece of text that itself supports the value: never join two separate parts of a sentence. If you cannot quote it, the value is null.\n- license_states: only states they say they are licensed in. states_not_licensed: states they say they are not (or not yet) licensed in. \"not licensed in California yet\" is states_not_licensed [\"CA\"], never \"not stated\".\n- certification_statement is what they say about their QME certification. intent is what they want next. Wanting or being interested in becoming a QME is intent, not a certification status: use \"not_stated\" unless they say they hold the certification, say they are actively working toward it (course taken, exam scheduled or passed, application filed), or say they are not certified. Saying they are not a QME yet, or have not taken the course, is \"says_not_certified\". A certification that lapsed or expired is \"says_lapsed\", even if they are retaking the exam; their intent is then \"returning_qme\", never \"established_qme_joining\". \"established_qme_joining\" is only for someone who says they currently hold the certification.\n- intent \"explore_qme_certification\" only when they say they want to become a QME, start QME work or get certified. Asking in general what the company offers is \"other\" or \"unclear\".\n- call_availability is only a time window for a call: days, times of day. A preferred channel (\"email is best\") is not availability: leave it null. It says nothing about capacity to perform evaluations.\n- A physician licensed outside California is not rejected: note in ambiguities what the coordinator should ask.\n- ambiguities lists only a gap or a contradiction that stops the coordinator from preparing the first call (for example: no state named, intent unclear, a statement that contradicts another). Never list something the message or previously_stated already answers, a detail the first conversation will naturally cover, or the physician's own questions (those go in \"questions\").\n- Do not assess eligibility, score the physician, or promise anything.\n- proposed_reply: a short, warm email from the recruiting team that answers what they asked where possible in general terms, proposes a first conversation, and asks only for what is missing for that conversation. Always open with \"Hello,\" (the workflow adds the name; you never receive it). The team already has their name, email and phone from the form: never ask for contact details. Never ask for something the message or previously_stated already says (for example a state they already named, or whether they hold a California license when they said they do not). Do not confirm or accept a specific time on the team's behalf: acknowledge when they said they are available and say the team will propose a time. Plain text, no subject line, no em dashes, end with \"Best regards,\" on its own line (the workflow adds the signature). Do not invent facts about the company, fees, timelines or acceptance. Never suggest they could perform evaluations, or work with the group in the meantime, before their certification is current. When known_to_team is true, do not ask for background the team already holds (specialty, license, certification history): answer what they asked and propose a conversation." },
    { role: 'user', content: JSON.stringify(input) },
  ],
};
return [{ json: { contact, previously, needsModel: true, reused: false, modelRequest } }];

// The model proposes; this code checks. A value is kept only if its quote is found word for
// word in the message AND the quote itself supports the value (state named, time words, etc.).
// Anything else is dropped and flagged. An unusable reply fails the attempt.
const prep = $('Prepare interpretation').first().json;
const c = prep.contact, previously = prep.previously || {};
const flags = [];
let raw = ((($input.first().json.choices || [])[0] || {}).message || {}).content || '';
raw = String(raw).replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/, '');
let m;
try { m = JSON.parse(raw); } catch (e) { throw new Error('Model reply is not valid JSON'); }
if (!m || typeof m !== 'object' || Array.isArray(m)) throw new Error('Model reply is not a JSON object');

const norm = s => String(s ?? '').toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/\s+/g, ' ').trim();
const unquote = s => String(s ?? '').trim().replace(/^["'“‘]+|["'.”’]+$/g, '').trim();
const source = norm(c.message);
const quoteOf = f => { const q = unquote(f && f.evidence); return q && source.includes(norm(q)) ? q : null; };
const drop = (name, why) => flags.push('unsupported:' + name + (why ? ' (' + why + ')' : ''));

const STATES = { AL: 'alabama', AK: 'alaska', AZ: 'arizona', AR: 'arkansas', CA: 'california', CO: 'colorado', CT: 'connecticut', DE: 'delaware', DC: 'district of columbia', FL: 'florida', GA: 'georgia', HI: 'hawaii', ID: 'idaho', IL: 'illinois', IN: 'indiana', IA: 'iowa', KS: 'kansas', KY: 'kentucky', LA: 'louisiana', ME: 'maine', MD: 'maryland', MA: 'massachusetts', MI: 'michigan', MN: 'minnesota', MS: 'mississippi', MO: 'missouri', MT: 'montana', NE: 'nebraska', NV: 'nevada', NH: 'new hampshire', NJ: 'new jersey', NM: 'new mexico', NY: 'new york', NC: 'north carolina', ND: 'north dakota', OH: 'ohio', OK: 'oklahoma', OR: 'oregon', PA: 'pennsylvania', RI: 'rhode island', SC: 'south carolina', SD: 'south dakota', TN: 'tennessee', TX: 'texas', UT: 'utah', VT: 'vermont', VA: 'virginia', WA: 'washington', WV: 'west virginia', WI: 'wisconsin', WY: 'wyoming' };

function textField(name, supports) {
  const f = m[name] || {};
  let v = f.value;
  if (v === null || v === undefined || v === '') return { value: null, evidence: null };
  if (typeof v !== 'string') { drop(name, 'not text'); return { value: null, evidence: null }; }
  const q = quoteOf(f);
  if (!q) { drop(name, 'quote not found in the message'); return { value: null, evidence: null }; }
  if (supports && !supports(v, q)) { drop(name, 'quote does not support the value'); return { value: null, evidence: null }; }
  return { value: v.trim(), evidence: q };
}

// A state is kept only if the quote names it, with or without a negation as the field requires.
function statesField(name, negative) {
  const f = m[name] || {};
  let v = f.value;
  if (v === null || v === undefined || (Array.isArray(v) && !v.length)) return { value: null, evidence: null };
  if (!Array.isArray(v)) v = [v];
  const q = quoteOf(f);
  const kept = [];
  for (const s of v) {
    const code = String(s).trim().toUpperCase();
    const named = STATES[code];
    if (!named) { drop(name, 'not a US state: ' + s); continue; }
    if (!q) { drop(name, 'quote not found in the message'); continue; }
    const nq = norm(q);
    let at = nq.indexOf(named);
    if (at < 0) { const mm = new RegExp('\\b' + code + '\\b').exec(q); at = mm ? norm(q.slice(0, mm.index)).length : -1; }
    if (at < 0) { drop(name, code + ' is not named in the quote'); continue; }
    const before = nq.slice(Math.max(0, at - 40), at);
    const negated = /\b(not|never|no longer)\b|n't\b/.test(before);
    if (negated !== negative) { drop(name, code + (negative ? ' is not negated in the quote' : ' is negated in the quote')); continue; }
    kept.push(code);
  }
  return kept.length ? { value: [...new Set(kept)], evidence: q } : { value: null, evidence: null };
}

function enumField(name, allowed, fallback, needs) {
  const f = m[name] || {};
  const v = f.value;
  if (!allowed.includes(v)) { if (v !== null && v !== undefined) flags.push('invalid_value:' + name); return { value: fallback, evidence: null }; }
  if (v === fallback) return { value: v, evidence: null };
  const q = quoteOf(f);
  if (!q) { drop(name, 'quote not found in the message'); return { value: fallback, evidence: null }; }
  if (needs[v] && !needs[v].test(q)) { drop(name, 'quote does not support ' + v); return { value: fallback, evidence: null }; }
  return { value: v, evidence: q };
}

const words = s => norm(s).split(/[^a-z]+/).filter(w => w.length >= 4).map(w => w.slice(0, 5));
const TIME = /\b(mon|tues?|wed|thur?s?|fri|sat|sun)[a-z]*\b|weekday|weekend|morning|afternoon|evening|\bnoon\b|lunch|\d{1,2}\s?(am|pm)\b|\d{1,2}:\d{2}|today|tomorrow|this week|next week/i;

const result = {
  specialty: textField('specialty', (v, q) => words(v).some(w => norm(q).includes(w))),
  license_states: statesField('license_states', false),
  states_not_licensed: statesField('states_not_licensed', true),
  certification_statement: enumField('certification_statement',
    ['says_certified_qme', 'says_lapsed', 'says_in_progress', 'says_not_certified', 'not_stated'], 'not_stated',
    { says_certified_qme: /QME|certif/i, says_lapsed: /laps|expir/i, says_in_progress: /course|exam|appl|certif|QME/i, says_not_certified: /\bnot\b|n't|\byet\b|never/i }),
  intent: enumField('intent',
    ['explore_qme_certification', 'established_qme_joining', 'returning_qme', 'other', 'unclear'], 'unclear',
    { explore_qme_certification: /QME|certif|evaluat/i, established_qme_joining: /QME|evaluat|panel/i, returning_qme: /QME|certif|exam|return|back/i }),
  call_availability: textField('call_availability', (v, q) => TIME.test(q)),
  questions: Array.isArray(m.questions) ? m.questions.filter(x => typeof x === 'string').slice(0, 5) : [],
  ambiguities: Array.isArray(m.ambiguities) ? m.ambiguities.filter(x => typeof x === 'string').slice(0, 5) : [],
  flags,
  source: 'model',
};
// An open question about licensure in a state the message already speaks to is dropped,
// unless it asks about plans (applying, obtaining).
const statedStates = [...(result.license_states.value || []), ...(result.states_not_licensed.value || []), ...(previously.license_states || [])];
result.ambiguities = result.ambiguities.filter(q => {
  const asksPlan = /plan|apply|obtain|pursu|intend/i.test(q);
  const aboutStated = statedStates.some(code => new RegExp('\\b' + code + '\\b').test(q) || norm(q).includes(STATES[code]));
  const aboutLicence = /licen[cs]/i.test(q);
  if (aboutLicence && aboutStated && !asksPlan) { flags.push('dropped_question:already_stated_licensure'); return false; }
  return true;
});
// Cross-checks between fields.
if (result.intent.value === 'established_qme_joining' && result.certification_statement.value !== 'says_certified_qme') {
  drop('intent', 'established QME without a stated current certification'); result.intent = { value: 'unclear', evidence: null };
}
if (result.intent.value === 'returning_qme' && result.certification_statement.value !== 'says_lapsed') {
  drop('intent', 'returning QME without a stated lapse'); result.intent = { value: 'unclear', evidence: null };
}

// The reply must say something; greeting and signature are added here, never by the model.
let body = String(m.proposed_reply ?? '');
body = body.replace(/^\s*(hello|hi|dear[^,\n]*)\s*,/i, '').replace(/\s*(best regards|kind regards|warm regards|sincerely|regards)\s*,?[\s\S]*$/i, '').trim();
if (body.replace(/\s+/g, ' ').length < 60) throw new Error('No usable proposed reply in the model output');
result.proposed_reply = (c.lastName ? 'Dear Dr. ' + c.lastName : 'Hello') + ',\n\n' + body + '\n\nBest regards,\n[Your name], Expedient recruiting';

// Review routing is ordinary code, not model judgment.
const v = c.verifiedQmeStatus, s = result.certification_statement.value;
const contradicts =
  (v === 'certified_qme' && ['says_not_certified', 'says_in_progress', 'says_lapsed'].includes(s)) ||
  (v === 'not_certified' && s === 'says_certified_qme') ||
  (v === 'in_progress' && s === 'says_not_certified');
const states = result.license_states.value || previously.license_states || [];
const notCA = (result.states_not_licensed.value || []).includes('CA');
const outsideCalifornia = notCA || (states.length > 0 && !states.includes('CA'));
const noStateForNewContact = states.length === 0 && !notCA && !v;
if (contradicts) {
  result.review_status = 'conflict_with_verified_record';
  flags.push('conflict:verified_qme_status=' + v + ',message_says=' + s);
} else if (outsideCalifornia || noStateForNewContact || result.intent.value === 'unclear' || result.ambiguities.length) {
  result.review_status = 'needs_clarification';
  if (outsideCalifornia) flags.push('clarify:not_licensed_in_california');
  if (noStateForNewContact) flags.push('clarify:license_state_not_stated');
} else {
  result.review_status = 'ready_for_review';
}
return [{ json: { contact: c, result } }];

// Suggestions go to separate ai_inquiry_* properties. Lifecycle stage, owner and any
// staff-verified value are never written by this workflow.
const cfg = $('Configuration').first().json.cfg, P = cfg.props;
const r = $('Check the interpretation').isExecuted ? $('Check the interpretation').first().json.result : $('Prepare interpretation').first().json.result;
const ns = v => (v === null || v === undefined || v === '' ? 'not stated' : v);
const yes = (r.license_states && r.license_states.value) || [];
const no = (r.states_not_licensed && r.states_not_licensed.value) || [];
const states = [yes.length ? yes.join(', ') : '', no.length ? 'not licensed in ' + no.join(', ') : ''].filter(Boolean).join('; ');
const properties = {
  [P.sugSpecialty]: ns(r.specialty.value),
  [P.sugLicenseStates]: ns(states),
  [P.sugCertification]: r.certification_statement.value,
  [P.sugIntent]: r.intent.value,
  [P.sugCallWindow]: ns(r.call_availability.value),
  [P.sugReviewStatus]: r.review_status,
  [P.sugFlags]: (r.flags || []).join('; ') || 'none',
  [P.sugRef]: $('Configuration').first().json.submission_key,
};
return [{ json: { properties } }];

// Every page of the contact's task associations, split into batch-read chunks of 100.
const ids = $input.all().flatMap(i => (i.json.results || []).map(r => String(r.toObjectId)));
const chunks = [];
for (let i = 0; i < ids.length; i += 100) chunks.push({ json: { ids: ids.slice(i, i + 100) } });
return chunks.length ? chunks : [{ json: { ids: [] } }];

// One open review task per physician, with subsequent inquiries appended. Decided by plain code:
//  reconciled: a task carrying THIS submission's reference already exists (an earlier attempt
//              created it but never got the answer), so nothing is created;
//  appended:   the physician already has an open review task from this workflow;
//  created:    otherwise, one new task, associated to the contact.
const cfgItem = $('Configuration').first().json;
const cfg = cfgItem.cfg, key = cfgItem.submission_key;
const r = $('Check the interpretation').isExecuted ? $('Check the interpretation').first().json.result : $('Prepare interpretation').first().json.result;
const c = $('Prepare interpretation').first().json.contact;
const tasks = $input.all().flatMap(i => (i.json.results || []).map(t => ({ id: String(t.id), ...t.properties })));
const ref = 'ref:' + key;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ns = v => (v === null || v === undefined || v === '' || (Array.isArray(v) && !v.length)) ? '<i>not stated</i>' : esc(Array.isArray(v) ? v.join(', ') : v);
const label = {
  says_certified_qme: 'says they are a certified QME', says_lapsed: 'says their certification lapsed', says_in_progress: 'says certification is in progress',
  says_not_certified: 'says they are not certified', not_stated: 'not stated',
  explore_qme_certification: 'exploring QME certification', established_qme_joining: 'established QME looking at the group',
  returning_qme: 'former QME looking to return', other: 'other request', unclear: 'unclear',
  ready_for_review: 'Ready for review', needs_clarification: 'Needs clarification',
  conflict_with_verified_record: 'Conflicts with the verified record', needs_information: 'Needs information',
  certified_qme: 'certified QME', in_progress: 'in progress', not_certified: 'not certified',
};
const quote = f => f && f.evidence ? ' <span style="color:#666">("' + esc(f.evidence) + '")</span>' : '';
const notLic = r.states_not_licensed && r.states_not_licensed.value;
const section =
  '<p><b>' + esc(label[r.review_status] || r.review_status) + '</b>. Nothing has been sent to the physician.</p>' +
  '<p><b>What they wrote</b><br>' + esc(c.message || '(empty message)') + '</p>' +
  '<p><b>Suggested reading, from their own words</b><br>' +
  'Specialty: ' + ns(r.specialty.value) + quote(r.specialty) + '<br>' +
  'Licensed in: ' + ns(r.license_states.value) + quote(r.license_states) + '<br>' +
  (notLic ? 'Says not licensed in: ' + ns(notLic) + quote(r.states_not_licensed) + '<br>' : '') +
  'Certification: ' + esc(label[r.certification_statement.value] || r.certification_statement.value) + quote(r.certification_statement) + '<br>' +
  'Looking for: ' + esc(label[r.intent.value] || r.intent.value) + quote(r.intent) + '<br>' +
  'Available for a first call: ' + ns(r.call_availability.value) + quote(r.call_availability) + ' (a call window, not evaluation capacity)</p>' +
  (c.verifiedQmeStatus ? '<p><b>Verified record kept as is</b>: QME status ' + esc(label[c.verifiedQmeStatus] || c.verifiedQmeStatus) + (r.review_status === 'conflict_with_verified_record' ? '. The new message does not match it; please check with the physician.' : '') + '</p>' : '') +
  ((r.ambiguities || []).length ? '<p><b>To clarify</b><br>' + r.ambiguities.map(esc).join('<br>') + '</p>' : '') +
  '<p><b>Proposed reply</b> (edit, then send it yourself)<br>' + esc(r.proposed_reply).replace(/\n/g, '<br>') + '</p>' +
  '<p style="color:#999;font-size:11px">' + cfg.taskMarker + ' ' + ref + '</p>';

const exact = tasks.find(t => (t.hs_task_body || '').includes(ref));
if (exact) return [{ json: { action: 'reconciled', taskId: exact.id } }];

const conflict = r.review_status === 'conflict_with_verified_record';
const open = tasks.find(t => (t.hs_task_body || '').includes(cfg.taskMarker) && t.hs_task_status !== 'COMPLETED');
if (open) {
  const body = (open.hs_task_body || '') + '<hr><p><b>New inquiry from the same physician</b>, received ' + esc(new Date(cfgItem.conversion_at).toISOString().slice(0, 16).replace('T', ' ')) + ' UTC</p>' + section;
  // Priority is only ever raised (a new conflict), never sent on an ordinary append.
  const properties = { hs_task_body: body };
  if (conflict) properties.hs_task_priority = 'HIGH';
  return [{ json: { action: 'appended', taskId: open.id, request: { properties } } }];
}

// Due: next weekday (no holiday calendar) at 10:00 in Los Angeles, converted to UTC.
const now = cfg.now ? new Date(cfg.now) : new Date();
function partsIn(tz, d) {
  const o = {};
  for (const p of new Intl.DateTimeFormat('en-US', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(d)) o[p.type] = p.value;
  return o;
}
function offsetMs(tz, utcMs) {
  const o = partsIn(tz, new Date(utcMs));
  return Date.UTC(+o.year, +o.month - 1, +o.day, +o.hour, +o.minute, +o.second) - utcMs;
}
function nextWeekdayAt(tz, hour, from) {
  const o = partsIn(tz, from);
  const y = +o.year, mo = +o.month - 1;
  let d = +o.day + 1;
  while ([0, 6].includes(new Date(Date.UTC(y, mo, d)).getUTCDay())) d++;
  const wall = Date.UTC(y, mo, d, hour);
  let t = wall - offsetMs(tz, wall);
  t = wall - offsetMs(tz, t);
  return new Date(t);
}
const dueAt = nextWeekdayAt(cfg.timeZone, cfg.dueHourLocal, now);
const who = [c.firstName, c.lastName].filter(Boolean).join(' ') || 'Unnamed physician';
const request = {
  properties: {
    hs_task_subject: 'Physician inquiry: ' + who + (c.credentials ? ', ' + c.credentials : '') + ' (review and reply)',
    hs_task_body: section,
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: conflict ? 'HIGH' : 'MEDIUM',
    hs_task_type: 'TODO',
    hs_timestamp: dueAt.toISOString(),
    hubspot_owner_id: String(cfg.recruitingOwnerId),
  },
  associations: [{ to: { id: c.id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 204 }] }],
};
return [{ json: { action: 'created', request } }];

